        if (!data.stories.length) { ui.alert(T('Aucun texte vivant visible dans la port\u00E9e choisie (les textes vectoris\u00E9s ne sont pas lus).', 'No visible live text in the chosen scope (outlined text cannot be read).')); return null; }
        res = analyzeStories(data.stories, o);
